INSERT INTO courses (title, description, category, price, instructor_id, enrollment_count, status, created_at, updated_at) VALUES
  ('강남 직영 카페 · 무인 주문 로봇 실증', '일 평균 방문객 480명, 좌석 42석. 매장 후면에 220V 전용 콘센트 2구와 기가 유선망을 제공합니다. 피크타임(11~14시) 외 시간대 실증 가능.', 'BACKEND', 1200000.00, 10, 12, 'ACTIVE', NOW(6), NOW(6)),
  ('베이커리 3개점 · 재고 예측 센서 실증', '가맹 3개점 동시 적용 가능. 진열대별 판매 데이터 일 단위 제공, 폐기율 개선 검증에 적합합니다.', 'BACKEND', 950000.00, 10, 5, 'ACTIVE', NOW(6), NOW(6)),
  ('대형 마트 3개점 · 스마트 선반 실증', '주말 일 방문객 6,000명 규모. 진열 매대 12m 구간을 실증 전용으로 배정하며, POS 연동 데이터는 익명화 후 제공합니다.', 'FRONTEND', 2400000.00, 11, 21, 'ACTIVE', NOW(6), NOW(6)),
  ('편의점 야간 무인화 실증', '22시~06시 무인 운영 구간. 출입 인증, 도난 방지, 결제 흐름을 통합 검증할 수 있습니다.', 'FRONTEND', 1650000.00, 11, 8, 'ACTIVE', NOW(6), NOW(6)),
  ('수도권 물류센터 · 자율주행 AGV 실증', '연면적 12,000㎡ 상온 창고. 통로 폭 3.2m, 층고 9m. 야간 셧다운 시간대 4시간을 실증 슬롯으로 개방합니다.', 'DEVOPS', 5600000.00, 12, 34, 'ACTIVE', NOW(6), NOW(6)),
  ('콜드체인 창고 · 온도 이탈 감지 실증', '냉동(-25도)·냉장(2도) 구역 분리 운영. 기존 온도 로거 데이터 6개월분을 비교군으로 제공합니다.', 'DEVOPS', 3800000.00, 12, 11, 'ACTIVE', NOW(6), NOW(6)),
  ('종합병원 외래 · 문진 AI 실증', '일 외래 1,200명 규모 3차 병원. IRB 승인 절차 지원하며, 실증 데이터는 원내 폐쇄망에서만 처리합니다.', 'DATA_SCIENCE', 4800000.00, 13, 27, 'ACTIVE', NOW(6), NOW(6)),
